import os, json
RLM_SESSION_DIR = os.environ['RLM_SESSION_DIR']
sessions_file = os.path.join(RLM_SESSION_DIR, '../../sessions/' + os.path.basename(RLM_SESSION_DIR) + '.jsonl')

with open(sessions_file, 'r') as f:
    lines = f.readlines()

# Parse all JSON objects
data = []
for line in lines:
    if line.strip():
        try:
            obj = json.loads(line)
            data.append(obj)
        except:
            pass

# Find messages with grid content
print("Looking for grid content...")
for i, obj in enumerate(data):
    msg = obj.get('message', {})
    role = msg.get('role', '')
    text = ''
    for c in msg.get('content', []):
        if isinstance(c, dict) and c.get('type') == 'text':
            text += c.get('text', '')
        elif isinstance(c, dict) and c.get('type') == 'thinking':
            # Skip thinking
            continue

    if any(kw in text for kw in ['Test input', 'Demo pair']):
        print(f"Line {i}: role={role[:20]} ... |{text[:300]}|")
